const containerId = "equity-chart";
let container = document.getElementById(containerId);

if (!container) {
  container = document.createElement("div");
  container.id = containerId;
  document.body.appendChild(container);
}

function loadPlotly() {
  if (window.Plotly) return Promise.resolve();

  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://cdn.plot.ly/plotly-2.35.2.min.js";
    script.onload = resolve;
    script.onerror = () => reject(new Error("Failed to load Plotly."));
    document.head.appendChild(script);
  });
}

async function renderChart(jsonUrl, targetId) {
  await loadPlotly();
  const response = await fetch(jsonUrl);
  if (!response.ok) throw new Error(`Failed to load chart data: ${response.status}`);
  const figureSpec = await response.json();
  await Plotly.newPlot(
    targetId,
    figureSpec.data,
    figureSpec.layout,
    { responsive: true, displaylogo: false }
  );
}

renderChart("../data/charts/cumulative_equity_curve.json", containerId);